// Des: Tests for ru-spen-guar and ru-kill-swit: free, paid, cap, kill
// Flo: temp db > record spend > check decisions around free quota, cap and kill
// I/O: numbers > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const spen = @import("ru-spen-guar.zig"); const kill = @import("ru-kill-swit.zig"); const inde = @import("st-page-inde.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
const Rig = struct { tmpz: std.testing.TmpDir, dirz: []u8, dbzz: @import("st-stor-sqli.zig").Db, pub fn up(self: *Rig) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); } pub fn down(self: *Rig) void { self.dbzz.close(); allo.free(self.dirz); self.tmpz.cleanup(); } };
const NOWZ: i64 = 1790000000000;
test "month number from epoch ms" { try std.testing.expectEqual(@as(i64, 197001), spen.montOf(0)); try std.testing.expectEqual(@as(i64, 202609), spen.montOf(1790000000000)); try std.testing.expectEqual(@as(i64, 197001), spen.montOf(-5)); }
test "default config is free-only: zero free credits means nothing passes" { var rig: Rig = undefined; try rig.up(); defer rig.down(); const dec = try spen.spenChek(&rig.dbzz, .{}, .zenr, 1, NOWZ, true); try std.testing.expect(!dec.okay); }
test "free credits cover cost until used up, then a paid call needs go and a cap" { var rig: Rig = undefined; try rig.up(); defer rig.down(); var conf: cfgz.Conf = .{}; conf.vend_free_cred.zenr = 10; const one = try spen.spenChek(&rig.dbzz, conf, .zenr, 5, NOWZ, false); try std.testing.expect(one.okay and !one.paid); try spen.spenRec(&rig.dbzz, .zenr, 5, 0, NOWZ); try spen.spenRec(&rig.dbzz, .zenr, 5, 0, NOWZ); const two = try spen.spenChek(&rig.dbzz, conf, .zenr, 1, NOWZ, false); try std.testing.expect(!two.okay); const tri = try spen.spenChek(&rig.dbzz, conf, .zenr, 1, NOWZ, true); try std.testing.expect(!tri.okay); try std.testing.expectEqualStrings("over capz_usdz_mont", tri.why); conf.capz_usdz_mont = 0.01; const fou = try spen.spenChek(&rig.dbzz, conf, .zenr, 5, NOWZ, true); try std.testing.expect(fou.okay and fou.paid); try std.testing.expectEqual(@as(u64, 5000), fou.micr); const fiv = try spen.spenChek(&rig.dbzz, conf, .zenr, 11, NOWZ, true); try std.testing.expect(!fiv.okay); }
test "spend adds up across vendors and resets next month" { var rig: Rig = undefined; try rig.up(); defer rig.down(); try spen.spenRec(&rig.dbzz, .zenr, 5, 5000, NOWZ); try spen.spenRec(&rig.dbzz, .deco, 2, 2000, NOWZ); try std.testing.expectEqual(@as(i64, 7000), try spen.spenTota(&rig.dbzz, NOWZ)); try std.testing.expectEqual(@as(i64, 5), try spen.spenUsed(&rig.dbzz, .zenr, NOWZ)); try std.testing.expectEqual(@as(i64, 0), try spen.spenTota(&rig.dbzz, NOWZ + 40 * 86400000)); }
test "kill switch halts everything, even free spend; survives reopen" { var rig: Rig = undefined; try rig.up(); defer rig.down(); var conf: cfgz.Conf = .{}; conf.vend_free_cred.deco = 100; try std.testing.expect((try spen.spenChek(&rig.dbzz, conf, .deco, 1, NOWZ, false)).okay); try kill.killSet(&rig.dbzz, true); const dec = try spen.spenChek(&rig.dbzz, conf, .deco, 1, NOWZ, true); try std.testing.expect(!dec.okay); try std.testing.expectEqualStrings("kill switch on", dec.why); try kill.killSet(&rig.dbzz, false); try std.testing.expect((try spen.spenChek(&rig.dbzz, conf, .deco, 1, NOWZ, false)).okay); }
